from AlgorithmImports import *
from datetime import timedelta, time


class FiveMinuteSpyOptionCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        spy = self.AddEquity("SPY", Resolution.Minute)
        spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = spy.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(timedelta(days=0), timedelta(days=365))
        )
        self.option_symbol = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None

        self.held_symbol = None
        self.held_expiry_date = None
        self.entry_fill_price = None

        self.entry_order_id = None
        self.exit_order_id = None
        self.spy_flatten_order_id = None
        self.expiration_block_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        # A TradeBarConsolidator only emits completed bars built from received data.
        # Missing minute data therefore does not create a synthetic five-minute bar.
        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not (self.fast.IsReady and self.slow.IsReady):
            return

        current_fast = self.fast.Current.Value
        current_slow = self.slow.Current.Value

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        end_time = bar.EndTime.time()
        eligible_time = time(9, 45) <= end_time <= time(14, 30)

        if bullish_cross and eligible_time:
            self.TryEnter(bar)

        self.previous_fast = current_fast
        self.previous_slow = current_slow

    def TryEnter(self, bar):
        if self.entry_order_id is not None or self.exit_order_id is not None:
            return

        if self.HasOptionHolding():
            return

        if self.expiration_block_date == self.Time.date():
            return

        chain = self.GetSpyOptionChain(self.CurrentSlice)
        if chain is None:
            self.Debug(f"{self.Time}: Entry skipped: no SPY option chain.")
            return

        today = self.Time.date()
        expiries = sorted({
            self.ExpiryDate(contract)
            for contract in chain
            if (self.ExpiryDate(contract) - today).days >= 7
        })

        if not expiries:
            self.Debug(f"{self.Time}: Entry skipped: no expiration at least 7 calendar days away.")
            return

        selected_expiry = expiries[0]
        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            spy_price = bar.Close

        minimum_strike = spy_price * 1.01
        candidates = [
            contract for contract in chain
            if self.ExpiryDate(contract) == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"{self.Time}: Entry skipped: no call at >= 101% SPY "
                f"for {selected_expiry}."
            )
            return

        selected = min(candidates, key=lambda c: (c.Strike, str(c.Symbol)))
        ticket = self.MarketOrder(selected.Symbol, 1, tag="Bullish 5-minute MA crossover")

        if ticket is not None:
            self.entry_order_id = ticket.OrderId
            self.Debug(
                f"{self.Time}: Entry submitted: {selected.Symbol}, "
                f"strike {selected.Strike}, expiry {selected_expiry}."
            )

    def OnData(self, data):
        self.FlattenUnexpectedSpyHolding()

        # Never intentionally carry a contract into its expiration date.
        if (
            self.held_symbol is not None
            and self.held_expiry_date is not None
            and self.Time.date() >= self.held_expiry_date
        ):
            self.expiration_block_date = self.Time.date()
            self.SubmitExit("Expiration processing")
            return

        if self.held_symbol is None or not self.Portfolio[self.held_symbol].Invested:
            return

        # Time stop at exactly 15:45 New York time on the prior trading day.
        if (
            self.Time.time() == time(15, 45)
            and self.Time.date() == self.PreviousTradingDay(self.held_expiry_date)
        ):
            self.SubmitExit("15:45 pre-expiration time stop")
            return

        # Profit target is evaluated only from a quote present in this Slice.
        if self.exit_order_id is not None or self.entry_fill_price is None:
            return

        contract = self.GetHeldContract(data)
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * 1.50:
            self.SubmitExit("50% profit target")

    def SubmitExit(self, reason):
        if self.held_symbol is None or self.exit_order_id is not None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        # Ensure a single active exit order for the held contract.
        self.Transactions.CancelOpenOrders(self.held_symbol, "Replacing existing exit order")
        ticket = self.MarketOrder(self.held_symbol, -quantity, tag=reason)

        if ticket is not None:
            self.exit_order_id = ticket.OrderId
            self.Debug(f"{self.Time}: Exit submitted: {self.held_symbol}; {reason}.")

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.held_expiry_date = self.ExpiryDateFromSymbol(order_event.Symbol)
                self.entry_fill_price = order_event.FillPrice
                self.entry_order_id = None
                self.Debug(
                    f"{self.Time}: Entry filled: {order_event.Symbol} "
                    f"at {order_event.FillPrice}."
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug(f"{self.Time}: Entry order closed without fill: {order_event.Symbol}.")
                self.entry_order_id = None

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"{self.Time}: Exit filled: {order_event.Symbol} "
                    f"at {order_event.FillPrice}."
                )
                self.exit_order_id = None
                self.held_symbol = None
                self.held_expiry_date = None
                self.entry_fill_price = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_id = None

        if (
            order_event.OrderId == self.spy_flatten_order_id
            and order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]
        ):
            self.spy_flatten_order_id = None

        # Assignment/exercise can be reflected before the next Slice.
        self.FlattenUnexpectedSpyHolding()

    def FlattenUnexpectedSpyHolding(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0 and self.spy_flatten_order_id is None:
            self.Debug(
                f"{self.Time}: Unexpected SPY equity position ({quantity}); "
                "liquidating possible exercise/assignment."
            )
            ticket = self.MarketOrder(
                self.spy,
                -quantity,
                tag="Flatten unexpected exercise/assignment SPY position"
            )
            if ticket is not None:
                self.spy_flatten_order_id = ticket.OrderId

    def GetSpyOptionChain(self, data):
        if data is None or data.OptionChains is None:
            return None

        for chain in data.OptionChains.Values:
            if chain.Underlying.Symbol == self.spy:
                return chain

        return None

    def GetHeldContract(self, data):
        if data is None or data.OptionChains is None or self.held_symbol is None:
            return None

        for chain in data.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == self.held_symbol:
                    return contract

        return None

    def HasOptionHolding(self):
        for item in self.Portfolio:
            if item.Key.SecurityType == SecurityType.Option and item.Value.Invested:
                return True
        return False

    def PreviousTradingDay(self, expiry_date):
        expiry_midnight = datetime.combine(expiry_date, time.min)
        return self.Securities[self.spy].Exchange.Hours.GetPreviousTradingDay(
            expiry_midnight
        ).date()

    def ExpiryDate(self, contract):
        return contract.Expiry.date()

    def ExpiryDateFromSymbol(self, symbol):
        return symbol.ID.Date.date()
