from AlgorithmImports import *
from datetime import datetime, timedelta, time as clock_time


class SpyFiveMinuteCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        # Broad strike and expiration coverage, including calls at least 1% OTM.
        option.SetFilter(-50, 50, timedelta(days=0), timedelta(days=365))
        self.option_canonical_symbol = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None

        self.pending_entry_bar_end = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.held_option = None
        self.entry_fill_price = None
        self.blocked_entry_date = None

        # With the algorithm in New York time, this consolidator aligns bars to
        # five-minute New York clock boundaries: 09:30-09:35 is the first RTH bar.
        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteSpyBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteSpyBar(self, bar):
        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not (self.fast.IsReady and self.slow.IsReady):
            return

        current_fast = self.fast.Current.Value
        current_slow = self.slow.Current.Value

        crossed_up = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        bar_time = bar.EndTime.time()
        if crossed_up and clock_time(9, 45) <= bar_time <= clock_time(14, 30):
            self.pending_entry_bar_end = bar.EndTime

    def OnData(self, data):
        self.HandleUnexpectedSpyHolding()
        self.HandleExpirationProcessing()
        self.HandleOptionExit(data)

        # A consolidation event is raised before this Slice is delivered. Requiring
        # exact timestamp equality prevents a missed Slice from queuing a signal.
        if self.pending_entry_bar_end == self.Time:
            self.pending_entry_bar_end = None
            self.TryEnter(data)

    def TryEnter(self, data):
        if self.blocked_entry_date == self.Time.date():
            return

        if self.entry_order_id is not None or self.held_option is not None:
            return

        if self.Portfolio[self.spy].Invested:
            return

        spot = self.Securities[self.spy].Price
        if spot <= 0:
            self.Debug("Skipped entry: SPY has no valid current price.")
            return

        chain = None
        for candidate_chain in data.OptionChains.Values:
            if candidate_chain.Symbol == self.option_canonical_symbol:
                chain = candidate_chain
                break

        if chain is None:
            self.Debug("Skipped entry: no SPY option chain in Slice.")
            return

        minimum_expiry_date = self.Time.date() + timedelta(days=7)
        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry_date
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least 7 calendar days away.")
            return

        selected_expiry = expirations[0]
        minimum_strike = 1.01 * spot

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"Skipped entry: no call >= 101% SPY strike at {selected_expiry}."
            )
            return

        selected = min(candidates, key=lambda x: (float(x.Strike), str(x.Symbol)))
        ticket = self.MarketOrder(
            selected.Symbol,
            1,
            True,
            f"MA crossover entry; expiry {selected.Expiry.date()}"
        )
        self.entry_order_id = ticket.OrderId
        self.Debug(f"Entry submitted: {selected.Symbol}")

    def HandleOptionExit(self, data):
        if self.held_option is None:
            return

        if not self.Portfolio[self.held_option].Invested:
            if self.exit_order_id is None:
                self.held_option = None
                self.entry_fill_price = None
            return

        if self.exit_order_id is not None:
            return

        expiry = self.held_option.ID.Date
        previous_trading_day = self.PreviousSpyTradingDate(expiry)

        if (
            self.Time.date() == previous_trading_day
            and self.Time.time() == clock_time(15, 45)
        ):
            self.SubmitExit("15:45 pre-expiration time stop")
            return

        if self.entry_fill_price is None or self.entry_fill_price <= 0:
            return

        midpoint = self.OptionMidpointFromSlice(data, self.held_option)
        if midpoint is not None and midpoint >= 1.50 * self.entry_fill_price:
            self.SubmitExit("50% profit target")

    def HandleExpirationProcessing(self):
        if self.held_option is None:
            return

        if not self.Portfolio[self.held_option].Invested:
            return

        if self.Time.date() >= self.held_option.ID.Date.date():
            self.blocked_entry_date = self.Time.date()
            self.Debug(f"Expiration handling: liquidating {self.held_option}")
            self.SubmitExit("expiration processing")

    def SubmitExit(self, reason):
        if self.held_option is None or self.exit_order_id is not None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        for order in self.Transactions.GetOpenOrders(self.held_option):
            self.Transactions.CancelOrder(order.Id, "Replacing with option exit")

        ticket = self.MarketOrder(self.held_option, -quantity, True, reason)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted: {self.held_option}; {reason}")

    def OptionMidpointFromSlice(self, data, symbol):
        for chain in data.OptionChains.Values:
            for contract in chain:
                if contract.Symbol != symbol:
                    continue

                bid = float(contract.BidPrice)
                ask = float(contract.AskPrice)

                if bid > 0 and ask > 0:
                    return (bid + ask) / 2.0

                return None

        return None

    def PreviousSpyTradingDate(self, expiry):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        candidate = expiry.date() - timedelta(days=1)

        while not exchange_hours.IsDateOpen(
            datetime.combine(candidate, clock_time.min)
        ):
            candidate -= timedelta(days=1)

        return candidate

    def HandleUnexpectedSpyHolding(self):
        if not self.Portfolio[self.spy].Invested:
            return

        open_spy_orders = self.Transactions.GetOpenOrders(self.spy)
        if open_spy_orders:
            return

        quantity = self.Portfolio[self.spy].Quantity
        self.Debug(
            f"Unexpected SPY holding from exercise/assignment; liquidating {quantity} shares."
        )
        self.MarketOrder(self.spy, -quantity, True, "Unexpected exercise/assignment cleanup")

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self.entry_order_id:
