from AlgorithmImports import *
from datetime import datetime, timedelta, time


class FiveMinuteSpyOptionCrossoverAlgorithm(QCAlgorithm):
    def initialize(self):
        self.set_time_zone(TimeZones.NEW_YORK)
        self.set_start_date(2023, 4, 1)
        self.set_end_date(2026, 6, 30)
        self.set_cash(100000)

        self.spy = self.add_equity(
            "SPY",
            Resolution.MINUTE,
            data_normalization_mode=DataNormalizationMode.RAW
        ).symbol

        self.option = self.add_option("SPY", Resolution.MINUTE)
        self.option.set_filter(
            lambda universe: universe.strikes(-1000, 1000).expiration(
                timedelta(days=0),
                timedelta(days=365)
            )
        )

        self._minute_bars = {}
        self._minute_bar_date = None
        self._closes = []

        self._previous_fast = None
        self._previous_slow = None

        self._entry_order_id = None
        self._entry_contract = None
        self._held_contract = None
        self._entry_fill_price = None
        self._exit_order_id = None
        self._block_entries_on_date = None

    def on_data(self, data: Slice):
        self._handle_unexpected_spy_position()
        self._handle_expiration_safety()
        self._handle_exits(data)

        if self.spy in data.bars:
            self._process_spy_minute_bar(data.bars[self.spy], data)

    def on_order_event(self, order_event: OrderEvent):
        if self._entry_order_id is not None and order_event.order_id == self._entry_order_id:
            if order_event.status == OrderStatus.FILLED and order_event.fill_quantity > 0:
                self._held_contract = order_event.symbol
                self._entry_fill_price = order_event.fill_price
                self._entry_order_id = None
                self._entry_contract = None
                self.debug(
                    f"ENTRY filled {self._held_contract} at {self._entry_fill_price:.2f}"
                )
            elif order_event.status in (OrderStatus.CANCELED, OrderStatus.INVALID):
                self.debug(f"ENTRY canceled/invalid: {order_event.symbol}")
                self._entry_order_id = None
                self._entry_contract = None

        if self._exit_order_id is not None and order_event.order_id == self._exit_order_id:
            if order_event.status == OrderStatus.FILLED:
                self.debug(f"EXIT filled {order_event.symbol} at {order_event.fill_price:.2f}")
                self._exit_order_id = None
                self._held_contract = None
                self._entry_fill_price = None
            elif order_event.status in (OrderStatus.CANCELED, OrderStatus.INVALID):
                self._exit_order_id = None

    def _process_spy_minute_bar(self, bar: TradeBar, data: Slice):
        end = bar.end_time

        # SPY regular-session minute bars end at 09:31 through 16:00.
        if end.time() < time(9, 31) or end.time() > time(16, 0):
            return

        if self._minute_bar_date != end.date():
            self._minute_bars.clear()
            self._minute_bar_date = end.date()

        self._minute_bars[end] = bar

        # A five-minute bar ending at HH:05, HH:10, ... HH:55, 16:00.
        if end.minute % 5 != 0:
            self._prune_minute_cache(end)
            return

        expected_times = [end - timedelta(minutes=i) for i in range(4, -1, -1)]
        if not all(timestamp in self._minute_bars for timestamp in expected_times):
            # Do not synthesize a five-minute bar when any constituent minute is absent.
            self._prune_minute_cache(end)
            return

        five_minute_close = self._minute_bars[expected_times[-1]].close
        self._update_moving_averages(five_minute_close, end, data)

        self._prune_minute_cache(end)

    def _prune_minute_cache(self, current_end: datetime):
        cutoff = current_end - timedelta(minutes=5)
        for timestamp in list(self._minute_bars.keys()):
            if timestamp <= cutoff:
                del self._minute_bars[timestamp]

    def _update_moving_averages(self, close: float, bar_end: datetime, data: Slice):
        self._closes.append(close)
        if len(self._closes) > 20:
            self._closes.pop(0)

        if len(self._closes) < 20:
            return

        fast = sum(self._closes[-5:]) / 5.0
        slow = sum(self._closes) / 20.0

        bullish_cross = (
            self._previous_fast is not None
            and self._previous_slow is not None
            and self._previous_fast <= self._previous_slow
            and fast > slow
        )

        self._previous_fast = fast
        self._previous_slow = slow

        if not bullish_cross:
            return

        if not (time(9, 45) <= bar_end.time() <= time(14, 30)):
            return

        self._try_enter(data, close)

    def _try_enter(self, data: Slice, spy_price: float):
        if self._held_contract is not None or self._entry_order_is_open():
            return

        if self._block_entries_on_date == self.time.date():
            return

        if spy_price <= 0:
            self.debug("ENTRY skipped: invalid SPY price")
            return

        chain = self._get_spy_option_chain(data)
        if chain is None:
            self.debug("ENTRY skipped: no SPY option chain in Slice")
            return

        contracts = list(chain)
        minimum_expiry = self.time.date() + timedelta(days=7)

        eligible_expiries = sorted({
            contract.expiry.date()
            for contract in contracts
            if contract.right == OptionRight.CALL
            and contract.expiry.date() >= minimum_expiry
        })

        if not eligible_expiries:
            self.debug("ENTRY skipped: no expiration at least 7 calendar days away")
            return

        selected_expiry = eligible_expiries[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in contracts
            if contract.right == OptionRight.CALL
            and contract.expiry.date() == selected_expiry
            and contract.strike >= minimum_strike
        ]

        if not candidates:
            self.debug("ENTRY skipped: no qualifying OTM call at selected expiration")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.strike, str(contract.symbol))
        )[0]

        ticket = self.market_order(selected.symbol, 1)
        self._entry_order_id = ticket.order_id
        self._entry_contract = selected.symbol

        self.debug(
            f"ENTRY submitted {selected.symbol}; expiry={selected.expiry.date()}, "
            f"strike={selected.strike}, SPY={spy_price:.2f}"
        )

    def _handle_exits(self, data: Slice):
        if self._held_contract is None or self._entry_fill_price is None:
            return

        if self._exit_order_is_open():
            return

        expiry = self._held_contract.id.date.date()
        stop_date = self._previous_spy_trading_day(expiry)

        if self.time.date() == stop_date and self.time.time() >= time(15, 45):
            self._submit_exit("pre-expiration time stop")
            return

        contract = self._find_held_contract_in_slice(data)
        if contract is None:
            return

        bid = contract.bid_price
        ask = contract.ask_price

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self._entry_fill_price:
            self._submit_exit(
                f"50% profit target (midpoint={midpoint:.2f}, entry={self._entry_fill_price:.2f})"
            )

    def _handle_expiration_safety(self):
        if self._held_contract is None:
            return

        expiry = self._held_contract.id.date.date()
        if self.time.date() >= expiry:
            self._block_entries_on_date = self.time.date()
            self.debug(f"EXPIRATION safety liquidation for {self._held_contract}")
            self._submit_exit("expiration safety")

    def _handle_unexpected_spy_position(self):
        quantity = self.portfolio[self.spy].quantity
        if quantity == 0:
            return

        open_orders = self.transactions.get_open_orders(self.spy)
        if any(order.quantity * quantity < 0 for order in open_orders):
            return

        self.debug(
            f"UNEXPECTED SPY equity position ({quantity}); liquidating possible exercise/assignment"
        )
        self.market_order(self.spy, -quantity)

    def _submit_exit(self, reason: str):
        if self._held_contract is None or self._exit_order_is_open():
            return

        for order in self.transactions.get_open_orders(self._held_contract):
            if order.quantity < 0:
                self.transactions.cancel_order(order.id)

        quantity = self.portfolio[self._held_contract].quantity
        if quantity <= 0:
            return

        ticket = self.market_order(self._held_contract, -quantity)
        self._exit_order_id = ticket.order_id
        self.debug(f"EXIT submitted {self._held_contract}: {reason}")

    def _get_spy_option_chain(self, data: Slice):
        if self.option.symbol in data.option_chains:
            return data.option_chains[self.option.symbol]

        for chain in data.option_chains.values():
            if chain.underlying.symbol == self.spy:
                return chain

        return None

    def _find_held_contract_in_slice(self, data: Slice):
        for chain in data.option_chains.values():
            for contract in chain:
                if contract.symbol == self._held_contract:
                    return contract
        return None

    def _entry_order_is_open(self) -> bool:
        if self._entry_order_id is None:
            return False

        ticket = self.transactions.get_order_ticket(self._entry_order_id)
        return ticket is not None and ticket.status in (
            OrderStatus.NEW,
            OrderStatus.SUBMITTED,
            OrderStatus.PARTIALLY_FILLED,
            OrderStatus.UPDATE_SUBMITTED
        )

    def _exit_order_is_open(self) -> bool:
        if self._exit_order_id is None:
            return False

        ticket = self.transactions.get_order_ticket(self._exit_order_id)
        return ticket is not None and ticket.status in (
            OrderStatus.NEW,
            OrderStatus.SUBMITTED,
            OrderStatus.PARTIALLY_FILLED,
            OrderStatus.UPDATE_SUBMITTED
        )

    def _previous_spy_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.securities[self.spy].exchange.hours

        while not exchange_hours.is_date_open(candidate, False):
            candidate -= timedelta(days=1)

        return candidate
