        stop_date = self._previous_spy_trading_day(expiry)

        if self.time.date() == stop_date and self.time.time() >= time(15, 45):
            self._submit_exit("pre-expiration time stop")
            return

        contract = self._find_held_contract_in_slice(data)
        if contract is None:
            return

        bid = contract.bid_price
        ask = contract.ask_price

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self._entry_fill_price:
            self._submit_exit(
                f"50% profit target (midpoint={midpoint:.2f}, entry={self._entry_fill_price:.2f})"
            )

    def _handle_expiration_safety(self):
        if self._held_contract is None:
            return

        expiry = self._held_contract.id.date.date()
        if self.time.date() >= expiry:
            self._block_entries_on_date = self.time.date()
            self.debug(f"EXPIRATION safety liquidation for {self._held_contract}")
            self._submit_exit("expiration safety")

    def _handle_unexpected_spy_position(self):
        quantity = self.portfolio[self.spy].quantity
        if quantity == 0:
            return

        open_orders = self.transactions.get_open_orders(self.spy)
        if any(order.quantity * quantity < 0 for order in open_orders):
            return

        self.debug(
            f"UNEXPECTED SPY equity position ({quantity}); liquidating possible exercise/assignment"
        )
        self.market_order(self.spy, -quantity)

