        if self._entry_order_id is None:
            return False

        ticket = self.transactions.get_order_ticket(self._entry_order_id)
        return ticket is not None and ticket.status in (
            OrderStatus.NEW,
            OrderStatus.SUBMITTED,
            OrderStatus.PARTIALLY_FILLED,
            OrderStatus.UPDATE_SUBMITTED
        )

    def _exit_order_is_open(self) -> bool:
        if self._exit_order_id is None:
            return False

        ticket = self.transactions.get_order_ticket(self._exit_order_id)
        return ticket is not None and ticket.status in (
            OrderStatus.NEW,
            OrderStatus.SUBMITTED,
            OrderStatus.PARTIALLY_FILLED,
            OrderStatus.UPDATE_SUBMITTED
        )

    def _previous_spy_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.securities[self.spy].exchange.hours

        while not exchange_hours.is_date_open(candidate, False):
            candidate -= timedelta(days=1)

