                if not self.Portfolio[orderEvent.Symbol].Invested:
                    self.held_option = None
                    self.entry_price = None
                    self.exit_order_id = None
            elif orderEvent.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_id = None

    def _has_option_exposure(self):
        if self.entry_order_id is not None or self.exit_order_id is not None:
            return True

        return (
            self.held_option is not None
            and self.Portfolio[self.held_option].Invested
        )

    def _has_open_exit_order(self):
        return self.exit_order_id is not None

    def _find_contract_in_slice(self, slice, symbol):
        for chain in slice.OptionChains.Values:
            contract = chain.Contracts.get(symbol)
            if contract is not None:
                return contract
        return None

    def _handle_unexpected_spy_position(self):
        if self.Portfolio[self.spy].Invested:
            self.Debug("Unexpected SPY exercise/assignment position detected; liquidating SPY.")
            self.MarketOrder(self.spy, -self.Portfolio[self.spy].Quantity)
