            minute_bar = data.Bars.get(self.spy)
        except Exception:
            minute_bar = None

        if minute_bar is None:
            return

        bar_time = minute_bar.Time
        if not self._is_regular_session_minute(bar_time):
            return

        bucket_start = bar_time.replace(
            minute=(bar_time.minute // 5) * 5,
            second=0,
            microsecond=0
        )

        if self.current_bucket_start is None:
            self.current_bucket_start = bucket_start

        if bucket_start != self.current_bucket_start:
            self._complete_five_minute_bucket(data)
            self.current_bucket_start = bucket_start
            self.bucket_minutes = []

        self.bucket_minutes.append((bar_time, minute_bar.Close))

