        if self.current_bucket_start is None:
            return

        expected_times = [
            self.current_bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        # A missing minute makes this five-minute interval unusable. Nothing is
        # synthesized and neither moving average is updated.
        if (len(self.bucket_minutes) != 5 or
                [x[0] for x in self.bucket_minutes] != expected_times):
            self.bucket_minutes = []
            return

        close = self.bucket_minutes[-1][1]
        bar_end = self.current_bucket_start + timedelta(minutes=5)
        self.bucket_minutes = []

        self.fast.Update(bar_end, close)
        self.slow.Update(bar_end, close)

        current_fast = self.fast.Current.Value
        current_slow = self.slow.Current.Value

        crossed_up = (
            self.fast.IsReady and
            self.slow.IsReady and
            self.previous_fast is not None and
            self.previous_slow is not None and
            self.previous_fast <= self.previous_slow and
            current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        if not crossed_up:
            return

        if not (time(9, 45) <= bar_end.time() <= time(14, 30)):
            return

        self._try_enter(data, bar_end)

    def _try_enter(self, data: Slice, signal_time: datetime):
        if signal_time.date() in self.no_entry_dates:
            return

        if self.entry_order_id is not None or self._has_open_exit():
            return

        if self.held_option is not None and self.Portfolio[self.held_option].Quantity != 0:
            return

        chain = self._get_chain(data)
        if chain is None:
            self.Debug(f"{signal_time}: skipped entry; no option chain in Slice")
            return

        contracts = list(chain.Contracts.Values)
        today = self.Time.date()
        min_expiry = today + timedelta(days=7)

        valid_expiries = sorted({
            self._contract_expiry(contract)
            for contract in contracts
            if self._contract_expiry(contract) >= min_expiry
        })

        if not valid_expiries:
            self.Debug(f"{signal_time}: skipped entry; no expiry at least 7 calendar days away")
            return

        expiry = valid_expiries[0]
        underlying_price = self.Securities[self.spy].Price
        minimum_strike = underlying_price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Right == OptionRight.CALL
            and self._contract_expiry(contract) == expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(f"{signal_time}: skipped entry; no qualifying call at {expiry}")
            return

        candidates.sort(key=lambda c: (c.Strike, str(c.Symbol)))
        selected = candidates[0]

        self.held_option = selected.Symbol
        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.Debug(
            f"{signal_time}: submitted entry for {selected.Symbol} "
            f"(expiry {expiry}, strike {selected.Strike})"
        )

    def _handle_option_exits(self, data: Slice):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        expiry = self._symbol_expiry(self.held_option)
        today = self.Time.date()

        # Do not intentionally carry an option into its expiration date.
        if today >= expiry:
            self.no_entry_dates.add(today)
            self._submit_option_exit("expiration safety exit")
            return

        previous_trading_day = self._previous_trading_day(expiry)
        if today == previous_trading_day and self.Time.time() == time(15, 45):
            self._submit_option_exit("15:45 pre-expiration exit")
            return

        if self.entry_price is None or self._has_open_exit():
            return

        contract = self._get_held_contract(data)
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * 1.50:
            self._submit_option_exit(
                f"profit target exit at midpoint {midpoint:.2f}"
            )

    def _submit_option_exit(self, reason: str):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0 or self._has_open_exit():
            return

        for order_id in list(self.exit_order_ids):
            ticket = self.Transactions.GetOrderTicket(order_id)
            if ticket is not None and ticket.Status not in (
                OrderStatus.FILLED,
                OrderStatus.CANCELED,
                OrderStatus.INVALID
            ):
                ticket.Cancel()

        ticket = self.MarketOrder(self.held_option, -quantity)
        self.exit_order_ids.append(ticket.OrderId)
        self.Debug(f"{self.Time}: {reason}; submitted market exit for {self.held_option}")

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.FILLED:
                self.entry_price = order_event.FillPrice
                self.entry_order_id = None
                self.Debug(
                    f"{self.Time}: entry filled for {order_event.Symbol} "
                    f"at {self.entry_price:.2f}"
                )
            elif order_event.Status in (OrderStatus.CANCELED, OrderStatus.INVALID):
                self.Debug(f"{self.Time}: entry did not complete for {order_event.Symbol}")
                self.entry_order_id = None
                self.held_option = None
                self.entry_price = None

        if order_event.OrderId in self.exit_order_ids:
            if order_event.Status == OrderStatus.FILLED:
                self.Debug(
                    f"{self.Time}: exit filled for {order_event.Symbol} "
                    f"at {order_event.FillPrice:.2f}"
                )
                self.exit_order_ids.remove(order_event.OrderId)
                if self.Portfolio[order_event.Symbol].Quantity == 0:
                    self.held_option = None
                    self.entry_price = None
            elif order_event.Status in (OrderStatus.CANCELED, OrderStatus.INVALID):
                self.exit_order_ids.remove(order_event.OrderId)

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        ticket = None
        if self.equity_liquidation_order_id is not None:
            ticket = self.Transactions.GetOrderTicket(self.equity_liquidation_order_id)

        if ticket is not None and ticket.Status not in (
            OrderStatus.FILLED,
            OrderStatus.CANCELED,
            OrderStatus.INVALID
        ):
            return

        self.no_entry_dates.add(self.Time.date())
        ticket = self.MarketOrder(self.spy, -quantity)
        self.equity_liquidation_order_id = ticket.OrderId
        self.Debug(
            f"{self.Time}: unexpected SPY position ({quantity}) detected; "
            "submitted immediate market liquidation"
        )

    def _get_chain(self, data: Slice):
        try:
            return data.OptionChains.get(self.option_symbol)
        except Exception:
            return None

    def _get_held_contract(self, data: Slice):
        chain = self._get_chain(data)
        if chain is None:
            return None

        try:
            return chain.Contracts.get(self.held_option)
        except Exception:
            return None

    def _has_open_exit(self) -> bool:
        for order_id in self.exit_order_ids:
            ticket = self.Transactions.GetOrderTicket(order_id)
            if ticket is not None and ticket.Status not in (
                OrderStatus.FILLED,
                OrderStatus.CANCELED,
                OrderStatus.INVALID
            ):
                return True
        return False

    def _previous_trading_day(self, expiry):
        expiry_midnight = datetime(expiry.year, expiry.month, expiry.day)
        market_open = self.Securities[self.spy].Exchange.Hours.GetPreviousMarketOpen(
            expiry_midnight, False
        )
        return market_open.date()

