from datetime import datetime, timedelta, time


class SpyFiveMinuteOptionCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(0, 730)
        )
        self.option_symbol = option.Symbol

        self.closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.active_five_minute_end = None
        self.minute_bars = {}

        self.held_contract = None
        self.entry_price = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.exit_submitted = False
        self.expiration_day_block = None
        self.spy_flatten_pending = False

    def OnData(self, data: Slice):
        # Exercise/assignment protection: immediately flatten any unexpected SPY shares.
        if self.Portfolio[self.spy].Invested:
            if not self.spy_flatten_pending:
                self.Debug("Unexpected SPY equity position from exercise/assignment; liquidating.")
                self.MarketOrder(self.spy, -self.Portfolio[self.spy].Quantity)
                self.spy_flatten_pending = True
            return

        # Never intentionally hold an option into its expiration date.
        if self.held_contract is not None:
            expiration_date = self._expiration_date(self.held_contract)
            if self.Time.date() >= expiration_date:
                self.expiration_day_block = self.Time.date()
                self._submit_exit("expiration processing")
            else:
                self._check_time_stop()
                self._check_profit_target(data)

        if self.spy not in data.Bars:
            return

        self._update_five_minute_bar(data.Bars[self.spy], data)

    def _update_five_minute_bar(self, minute_bar: TradeBar, data: Slice):
        end_time = minute_bar.EndTime

        # Use only regular-session minute bars. Minute bars end at 09:31 through 16:00.
        if end_time.time() < time(9, 31) or end_time.time() > time(16, 0):
            return

        minutes_since_midnight = end_time.hour * 60 + end_time.minute
        boundary_minutes = ((minutes_since_midnight + 4) // 5) * 5
        five_end = end_time.replace(
            hour=boundary_minutes // 60,
            minute=boundary_minutes % 60,
            second=0,
            microsecond=0
        )

        # A new interval confirms that a prior interval lacking its boundary minute is missing.
        if self.active_five_minute_end is not None and five_end != self.active_five_minute_end:
            self._complete_five_minute_bar(self.active_five_minute_end, data)
            self.minute_bars = {}

        self.active_five_minute_end = five_end
        self.minute_bars[end_time] = minute_bar

        if end_time == five_end:
            self._complete_five_minute_bar(five_end, data)
            self.active_five_minute_end = None
            self.minute_bars = {}

    def _complete_five_minute_bar(self, five_end, data: Slice):
        expected_times = [five_end - timedelta(minutes=i) for i in range(4, -1, -1)]

        # Do not synthesize a five-minute bar if any constituent minute is absent.
        if not all(bar_time in self.minute_bars for bar_time in expected_times):
            return

        close = self.minute_bars[expected_times[-1]].Close
        self.closes.append(close)

        if len(self.closes) < 20:
            return

        values = list(self.closes)
        fast = sum(values[-5:]) / 5.0
        slow = sum(values) / 20.0

        bullish_crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        eligible_time = time(9, 45) <= five_end.time() <= time(14, 30)
        if bullish_crossover and eligible_time:
            self._try_enter(data)

    def _try_enter(self, data: Slice):
        if self.expiration_day_block == self.Time.date():
            return

        if self.held_contract is not None or self.entry_ticket is not None:
            return

        if self.exit_submitted:
            return

        if self.spy not in data.Bars:
            self.Debug("Skipped entry: no current SPY price.")
            return

        spy_price = data.Bars[self.spy].Close
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        contracts = []
        for chain in data.OptionChains.Values:
            for contract in chain:
                contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        minimum_expiration = self.Time.date() + timedelta(days=7)
        eligible_expirations = sorted({
            self._expiration_date(contract.Symbol)
            for contract in contracts
            if self._expiration_date(contract.Symbol) >= minimum_expiration
        })

        if not eligible_expirations:
            self.Debug("Skipped entry: no expiration at least seven calendar days away.")
            return

        selected_expiration = eligible_expirations[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in contracts
            if self._expiration_date(contract.Symbol) == selected_expiration
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike at selected expiration.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol}, expiry {selected_expiration}, "
            f"strike {selected.Strike:.2f}"
        )

