        if self.exit_submitted or self.held_contract is None or self.entry_price is None:
            return

        contract = self._find_contract_in_slice(data, self.held_contract)
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _check_time_stop(self):
        if self.exit_submitted or self.held_contract is None:
            return

        expiration_date = self._expiration_date(self.held_contract)
        prior_trading_day = self._previous_trading_day(expiration_date)

        if self.Time.date() == prior_trading_day and self.Time.time() == time(15, 45):
            self._submit_exit("15:45 pre-expiration time stop")

    def _submit_exit(self, reason: str):
        if self.exit_submitted or self.held_contract is None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None and self._is_open(self.exit_ticket.Status):
            self.exit_ticket.Cancel("Replacing open exit order")

        self.exit_ticket = self.MarketOrder(self.held_contract, -quantity)
        self.exit_submitted = True
        self.Debug(f"Exit submitted ({reason}): {self.held_contract}")

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.FillQuantity > 0:
                self.held_contract = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.Debug(
                    f"Entry filled: {order_event.Symbol} at {order_event.FillPrice:.2f}"
                )

            if not self._is_open(order_event.Status):
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.FillQuantity < 0:
                self.Debug(
                    f"Exit filled: {order_event.Symbol} at {order_event.FillPrice:.2f}"
                )

            if not self._is_open(order_event.Status):
                self.exit_ticket = None
                self.exit_submitted = False

                if self.held_contract is not None and not self.Portfolio[self.held_contract].Invested:
                    self.held_contract = None
                    self.entry_price = None

        if order_event.Symbol == self.spy and not self._is_open(order_event.Status):
            self.spy_flatten_pending = False

    def _find_contract_in_slice(self, data: Slice, symbol: Symbol):
        for chain in data.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == symbol:
                    return contract
        return None

    def _expiration_date(self, symbol: Symbol):
        expiry = symbol.ID.Date
        return expiry.date() if hasattr(expiry, "date") else expiry

    def _previous_trading_day(self, expiration_date):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        prior_open = exchange_hours.GetPreviousMarketOpen(
            datetime.combine(expiration_date, time.min),
            False
        )
        return prior_open.date()

    def _is_open(self, status):
        return status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )
