        if self.Portfolio[self.spy].Invested:
            if not self.spy_flatten_pending:
                self.Debug("Unexpected SPY equity position from exercise/assignment; liquidating.")
                self.MarketOrder(self.spy, -self.Portfolio[self.spy].Quantity)
                self.spy_flatten_pending = True
            return

        # Never intentionally hold an option into its expiration date.
        if self.held_contract is not None:
            expiration_date = self._expiration_date(self.held_contract)
            if self.Time.date() >= expiration_date:
                self.expiration_day_block = self.Time.date()
                self._submit_exit("expiration processing")
            else:
                self._check_time_stop()
                self._check_profit_target(data)

        if self.spy not in data.Bars:
            return

        self._update_five_minute_bar(data.Bars[self.spy], data)

    def _update_five_minute_bar(self, minute_bar: TradeBar, data: Slice):
        end_time = minute_bar.EndTime

        # Use only regular-session minute bars. Minute bars end at 09:31 through 16:00.
        if end_time.time() < time(9, 31) or end_time.time() > time(16, 0):
            return

        minutes_since_midnight = end_time.hour * 60 + end_time.minute
        boundary_minutes = ((minutes_since_midnight + 4) // 5) * 5
        five_end = end_time.replace(
            hour=boundary_minutes // 60,
            minute=boundary_minutes % 60,
            second=0,
            microsecond=0
        )

        # A new interval confirms that a prior interval lacking its boundary minute is missing.
        if self.active_five_minute_end is not None and five_end != self.active_five_minute_end:
            self._complete_five_minute_bar(self.active_five_minute_end, data)
            self.minute_bars = {}

        self.active_five_minute_end = five_end
        self.minute_bars[end_time] = minute_bar

        if end_time == five_end:
            self._complete_five_minute_bar(five_end, data)
            self.active_five_minute_end = None
            self.minute_bars = {}

