        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.At(15, 45),
            self._time_stop_check
        )

    def OnData(self, data: Slice):
        self._handle_unexpected_spy_position()
        self._handle_expiration_day()

        # This consumes a crossover produced by the consolidator immediately
        # when the corresponding minute Slice is available.
        self._process_pending_entry(data)

        self._check_profit_target(data)

    def _on_five_minute_bar(self, sender, bar: TradeBar):
        had_ready_averages = self._five_minute_closes.IsReady

        if had_ready_averages:
            previous_fast = sum(self._five_minute_closes[i] for i in range(5)) / 5.0
            previous_slow = sum(self._five_minute_closes[i] for i in range(20)) / 20.0

        self._five_minute_closes.Add(float(bar.Close))

        if not had_ready_averages or not self._five_minute_closes.IsReady:
            return

        current_fast = sum(self._five_minute_closes[i] for i in range(5)) / 5.0
        current_slow = sum(self._five_minute_closes[i] for i in range(20)) / 20.0

        is_bullish_cross = (
            previous_fast <= previous_slow
            and current_fast > current_slow
        )

        end_time = bar.EndTime.time()
        is_entry_time = dt_time(9, 45) <= end_time <= dt_time(14, 30)

        if is_bullish_cross and is_entry_time:
            self._pending_signal_end = bar.EndTime

            # Depending on engine event ordering, CurrentSlice may already be
            # populated. OnData also performs this check as a fallback.
            self._process_pending_entry(self.CurrentSlice)

    def _process_pending_entry(self, data):
        if self._pending_signal_end is None:
            return

        # A crossover must be evaluated only on its closing Slice.
        if self.Time != self._pending_signal_end:
            return

        if data is None:
            return

        try:
            self._try_enter(data)
        finally:
            # Signals are never queued for later selection.
            self._pending_signal_end = None

    def _try_enter(self, data: Slice):
        if self._no_entries_date == self.Time.date():
            return

        if self._entry_order_open or self._has_option_position():
            return

        try:
            chain = data.OptionChains[self.option_symbol]
        except (KeyError, TypeError):
            self.Debug(f"{self.Time}: Entry skipped; no SPY option chain in Slice.")
            return

        today = self.Time.date()
        minimum_expiry = today + timedelta(days=7)

        eligible_contracts = [
            contract for contract in chain
            if contract.Right == OptionRight.CALL
            and self._contract_expiry_date(contract) >= minimum_expiry
        ]

        if not eligible_contracts:
            self.Debug(f"{self.Time}: Entry skipped; no call expiry at least 7 calendar days away.")
            return

        selected_expiry = min(
            self._contract_expiry_date(contract)
            for contract in eligible_contracts
        )

        spy_price = float(self.Securities[self.spy].Price)
        if spy_price <= 0:
            self.Debug(f"{self.Time}: Entry skipped; SPY has no valid current price.")
            return

        minimum_strike = spy_price * 1.01
        candidates = [
            contract for contract in eligible_contracts
            if self._contract_expiry_date(contract) == selected_expiry
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"{self.Time}: Entry skipped; no call strike at least 1% above SPY "
                f"for {selected_expiry}."
            )
            return

        selected = min(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )

        self._entry_order_open = True
        self._entry_symbol = selected.Symbol
        ticket = self.MarketOrder(selected.Symbol, 1)
        self._entry_order_id = ticket.OrderId

        self.Debug(
            f"{self.Time}: Entering 1 {selected.Symbol}; "
            f"expiry={selected_expiry}, strike={selected.Strike}."
        )

    def _check_profit_target(self, data: Slice):
        if not self._has_option_position() or self._exit_order_open:
            return

        if self._entry_fill_price is None or self._entry_fill_price <= 0:
            return

        contract = self._find_held_contract(data)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self._entry_fill_price * 1.50:
            self._submit_option_exit(
                f"Profit target reached at midpoint {midpoint:.2f}."
            )

    def _time_stop_check(self):
        if not self._has_option_position() or self._exit_order_open:
            return

        if self._expiry_date is None:
            return

        if self.Time.date() == self._previous_spy_trading_date(self._expiry_date):
            self._submit_option_exit("15:45 time stop before expiration.")

    def _handle_expiration_day(self):
        if not self._has_option_position() or self._expiry_date is None:
            return

        if self.Time.date() >= self._expiry_date:
            self._no_entries_date = self.Time.date()
            self._submit_option_exit("Expiration-day protective liquidation.")

    def _submit_option_exit(self, reason: str):
        if not self._has_option_position() or self._exit_order_open:
            return

        for ticket in self.Transactions.GetOpenOrderTickets(self._held_option):
            ticket.Cancel("Cancelling open exit order before liquidation.")

        quantity = self.Portfolio[self._held_option].Quantity
        if quantity == 0:
            return

        self._exit_order_open = True
        ticket = self.MarketOrder(self._held_option, -quantity)
        self._exit_order_id = ticket.OrderId
        self.Debug(f"{self.Time}: Exiting {self._held_option}. {reason}")

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity == 0:
            self._spy_liquidation_open = False
            return

        if self._spy_liquidation_open:
            return

        self._spy_liquidation_open = True
        ticket = self.MarketOrder(self.spy, -quantity)
        self._spy_liquidation_order_id = ticket.OrderId
        self.Debug(
            f"{self.Time}: Unexpected SPY equity position ({quantity}) from "
            "exercise/assignment; submitting immediate liquidation."
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.OrderId == self._entry_order_id:
            if order_event.Status == OrderStatus.FILLED:
                self._entry_order_open = False
                self._held_option = order_event.Symbol
                self._entry_fill_price = float(order_event.FillPrice)
                self._expiry_date = self._symbol_expiry_date(order_event.Symbol)

                self.Debug(
                    f"{self.Time}: Entry filled for {self._held_option} at "
                    f"{self._entry_fill_price:.2f}."
                )
            elif order_event.Status in (OrderStatus.CANCELED, OrderStatus.INVALID):
                self._entry_order_open = False
                self._entry_order_id = None
                self._entry_symbol = None

        if order_event.OrderId == self._exit_order_id:
            if order_event.Status == OrderStatus.FILLED:
                self.Debug(
                    f"{self.Time}: Exit filled for {order_event.Symbol} at "
                    f"{float(order_event.FillPrice):.2f}."
                )
                self._clear_option_state()
            elif order_event.Status in (OrderStatus.CANCELED, OrderStatus.INVALID):
                self._exit_order_open = False
                self._exit_order_id = None

        if order_event.OrderId == self._spy_liquidation_order_id:
            if order_event.Status in (
                OrderStatus.FILLED,
                OrderStatus.CANCELED,
                OrderStatus.INVALID
            ):
                self._spy_liquidation_open = False
                self._spy_liquidation_order_id = None

    def _has_option_position(self) -> bool:
        return (
            self._held_option is not None
            and self.Portfolio[self._held_option].Quantity != 0
        )

    def _find_held_contract(self, data: Slice):
        if self._held_option is None:
            return None

        try:
            chain = data.OptionChains[self.option_symbol]
        except (KeyError, TypeError):
            return None

        for contract in chain:
            if contract.Symbol == self._held_option:
                return contract

        return None

    def _previous_spy_trading_date(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(
            datetime.combine(candidate, dt_time.min)
        ):
            candidate -= timedelta(days=1)

        return candidate

    @staticmethod
    def _contract_expiry_date(contract):
        return contract.Expiry.date()

    @staticmethod
    def _symbol_expiry_date(symbol):
        return symbol.ID.Date.date()

    def _clear_option_state(self):
        self._entry_order_id = None
        self._entry_order_open = False
        self._entry_symbol = None
        self._held_option = None
        self._entry_fill_price = None
        self._expiry_date = None
        self._exit_order_id = None
        self._exit_order_open = False

