        if data.Bars.ContainsKey(self.spy):
            self._consume_spy_minute_bar(data.Bars[self.spy], data)

    def _consume_spy_minute_bar(self, bar, data):
        end = bar.EndTime
        regular_open = time(9, 31)
        regular_close = time(16, 0)

        if end.time() < regular_open or end.time() > regular_close:
            return

        minutes_since_midnight = end.hour * 60 + end.minute
        bucket_minutes = ((minutes_since_midnight + 4) // 5) * 5
        bucket_end = datetime.combine(end.date(), time.min) + timedelta(minutes=bucket_minutes)

        if self.bucket_end is None or bucket_end != self.bucket_end:
            self.bucket_end = bucket_end
            self.expected_minute_end = end
            self.bucket_closes = []
            self.bucket_invalid = False

        if end != self.expected_minute_end:
            self.bucket_invalid = True

        self.bucket_closes.append(bar.Close)
        self.expected_minute_end = end + timedelta(minutes=1)

        if end != self.bucket_end:
            return

        # A valid five-minute bar requires all five real minute bars.
        if not self.bucket_invalid and len(self.bucket_closes) == 5:
            self._on_five_minute_bar(end, self.bucket_closes[-1], data)

        self.bucket_end = None
        self.expected_minute_end = None
        self.bucket_closes = []
        self.bucket_invalid = False

    def _on_five_minute_bar(self, bar_end, close, data):
        self.fast_closes.append(close)
        self.slow_closes.append(close)

        if len(self.fast_closes) < 5 or len(self.slow_closes) < 20:
            return

        fast = sum(self.fast_closes) / 5.0
        slow = sum(self.slow_closes) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if not bullish_cross:
            return

        if not (time(9, 45) <= bar_end.time() <= time(14, 30)):
            return

        if self.no_entry_date == self.Time.date():
            return

        if self.entry_order_id is not None or self._has_option_holding():
            return

        self._enter_from_current_chain(data, close)

    def _enter_from_current_chain(self, data, spy_price):
        if not data.OptionChains.ContainsKey(self.option_canonical):
            self.Debug("Entry skipped: no SPY option chain in current Slice.")
            return

        chain = data.OptionChains[self.option_canonical]
        today = self.Time.date()

        eligible_expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if (contract.Expiry.date() - today).days >= 7
        })

        if not eligible_expirations:
            self.Debug("Entry skipped: no expiration with at least 7 calendar DTE.")
            return

        selected_expiry = eligible_expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no eligible call strike in selected expiration.")
            return

        selected = min(candidates, key=lambda c: (float(c.Strike), str(c.Symbol)))
        ticket = self.MarketOrder(selected.Symbol, 1)

        if ticket is not None:
            self.entry_order_id = ticket.OrderId
            self.Debug(
                f"Entry submitted: {selected.Symbol} expiry={selected_expiry} "
                f"strike={selected.Strike}"
            )

    def _process_profit_target(self, data):
        if self.held_contract is None or self.entry_fill_price is None:
            return

        if self.exit_order_id is not None:
            return

        bid, ask = self._current_bid_ask(data, self.held_contract)
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * 1.50:
            self.Debug(
                f"Profit target reached for {self.held_contract}: "
                f"midpoint={midpoint:.2f}, entry={self.entry_fill_price:.2f}"
            )
            self._submit_option_exit("profit target")

    def _process_time_stop(self):
        if self.held_contract is None or self.exit_order_id is not None:
            return

        expiry = self.held_contract.ID.Date.date()
        previous_trading_day = self._previous_spy_trading_day(expiry)

        if self.Time.date() == previous_trading_day and self.Time.time() == time(15, 45):
            self.Debug(f"Time-stop exit submitted for {self.held_contract}.")
            self._submit_option_exit("15:45 pre-expiration time stop")

    def _process_expiration_exit(self):
        if self.held_contract is None:
            return

        expiry = self.held_contract.ID.Date.date()
        if self.Time.date() >= expiry:
            self.no_entry_date = self.Time.date()

            if self.exit_order_id is None:
                self.Debug(f"Expiration safety exit submitted for {self.held_contract}.")
                self._submit_option_exit("expiration safety")

    def _previous_spy_trading_day(self, expiration_date):
        day = expiration_date - timedelta(days=1)
        exchange = self.Securities[self.spy].Exchange

        while not exchange.DateIsOpen(datetime.combine(day, time.min)):
            day -= timedelta(days=1)

        return day

    def _current_bid_ask(self, data, symbol):
        if data.QuoteBars.ContainsKey(symbol):
            quote = data.QuoteBars[symbol]
            if quote.Bid is not None and quote.Ask is not None:
                return float(quote.Bid.Close), float(quote.Ask.Close)

        if data.OptionChains.ContainsKey(self.option_canonical):
            for contract in data.OptionChains[self.option_canonical]:
                if contract.Symbol == symbol:
                    return float(contract.BidPrice), float(contract.AskPrice)

        return 0.0, 0.0

    def _submit_option_exit(self, reason):
        if self.held_contract is None or self.exit_order_id is not None:
            return

        for order in self.Transactions.GetOpenOrders(self.held_contract):
            self.Transactions.CancelOrder(order.Id)

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        ticket = self.MarketOrder(self.held_contract, -quantity)
        if ticket is not None:
            self.exit_order_id = ticket.OrderId
            self.Debug(f"Exit submitted ({reason}): {self.held_contract}")

    def _has_option_holding(self):
        for security in self.Securities.Values:
            if security.Symbol.SecurityType == SecurityType.Option and security.Invested:
                return True
        return False

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        if self.spy_liquidation_order_id is None:
            self.Debug(
                f"Unexpected SPY exercise/assignment position detected "
                f"({quantity}); liquidating immediately."
            )
            ticket = self.MarketOrder(self.spy, -quantity)
            if ticket is not None:
                self.spy_liquidation_order_id = ticket.OrderId

    def OnOrderEvent(self, orderEvent):
        if orderEvent.OrderId == self.entry_order_id:
            if orderEvent.Status == OrderStatus.Filled:
                self.held_contract = orderEvent.Symbol
                self.entry_fill_price = float(orderEvent.FillPrice)
                self.entry_order_id = None
                self.Debug(
                    f"Entry filled: {self.held_contract} at {self.entry_fill_price:.2f}"
                )
            elif orderEvent.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.entry_order_id = None
                self.Debug(f"Entry order closed without fill: {orderEvent.Symbol}")

        if orderEvent.OrderId == self.exit_order_id:
            if orderEvent.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {orderEvent.Symbol} at {orderEvent.FillPrice:.2f}")
                self.exit_order_id = None
                self.held_contract = None
                self.entry_fill_price = None
            elif orderEvent.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.exit_order_id = None
                self.Debug(f"Exit order canceled/invalid: {orderEvent.Symbol}")

        if orderEvent.OrderId == self.spy_liquidation_order_id:
            if orderEvent.Status in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid):
                self.spy_liquidation_order_id = None
