from AlgorithmImports import *
from datetime import timedelta


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self._spy = self.AddEquity("SPY", Resolution.Minute).Symbol
        self.Securities[self._spy].SetDataNormalizationMode(DataNormalizationMode.Raw)

        option = self.AddOption("SPY", Resolution.Minute)
        self._option_symbol = option.Symbol
        option.SetFilter(-100, 100, timedelta(0), timedelta(days=365))

        self._fast = SimpleMovingAverage(5)
        self._slow = SimpleMovingAverage(20)

        # With regular-hours minute SPY data, this produces bars ending 09:35,
        # 09:40, ..., aligned to New York five-minute clock boundaries.
        self._five_minute = TradeBarConsolidator(timedelta(minutes=5))
        self._five_minute.DataConsolidated += self._on_five_minute_bar
        self.SubscriptionManager.AddConsolidator(self._spy, self._five_minute)

        self._pending_crossover_end = None
        self._held_option = None
        self._held_expiry = None
        self._entry_price = None

        self._entry_order_id = None
        self._exit_order_id = None
        self._spy_liquidation_order_id = None
        self._no_entry_date = None

        self.Schedule.On(
            self.DateRules.EveryDay(self._spy),
            self.TimeRules.At(15, 45),
            self._time_stop
        )

        self.Schedule.On(
            self.DateRules.EveryDay(self._spy),
            self.TimeRules.AfterMarketOpen(self._spy, 1),
            self._expiration_safety_check
        )

    def OnData(self, data: Slice):
        self._handle_unexpected_spy_position()

        # The crossover is evaluated only on the Slice at the completed
        # five-minute bar's end time; skipped signals are never queued.
        if self._pending_crossover_end is not None:
            if self.Time == self._pending_crossover_end:
                self._select_and_enter(data)
                self._pending_crossover_end = None
            elif self.Time > self._pending_crossover_end:
                self._pending_crossover_end = None

        self._check_profit_target(data)

    def _on_five_minute_bar(self, sender, bar: TradeBar):
        previous_ready = self._fast.IsReady and self._slow.IsReady
        previous_fast = self._fast.Current.Value if previous_ready else None
        previous_slow = self._slow.Current.Value if previous_ready else None

        # A missing consolidated bar produces no callback, so no indicator
        # update or synthetic/forward-filled interval is created.
        self._fast.Update(bar.EndTime, bar.Close)
        self._slow.Update(bar.EndTime, bar.Close)

        if not previous_ready or not (self._fast.IsReady and self._slow.IsReady):
            return

        bullish_cross = (
            previous_fast <= previous_slow and
            self._fast.Current.Value > self._slow.Current.Value
        )

        end_time = bar.EndTime
        eligible_time = (
            (end_time.hour > 9 or (end_time.hour == 9 and end_time.minute >= 45)) and
            (end_time.hour < 14 or (end_time.hour == 14 and end_time.minute <= 30))
        )

        if bullish_cross and eligible_time:
            self._pending_crossover_end = end_time

    def _select_and_enter(self, data: Slice):
        if self._no_entry_date == self.Time.date():
            return

        if self._held_option is not None and self.Portfolio[self._held_option].Invested:
            return

        if self._order_is_open(self._entry_order_id) or self._order_is_open(self._exit_order_id):
            return

        if self._option_symbol not in data.OptionChains:
            self.Debug(f"{self.Time}: entry skipped; no option chain.")
            return

        spy_price = self.Securities[self._spy].Price
        if spy_price <= 0:
            self.Debug(f"{self.Time}: entry skipped; invalid SPY price.")
            return

        chain = data.OptionChains[self._option_symbol]
        minimum_expiry = self.Time.date() + timedelta(days=7)

        eligible_expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not eligible_expiries:
            self.Debug(f"{self.Time}: entry skipped; no expiry at least 7 calendar days away.")
            return

        selected_expiry = eligible_expiries[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"{self.Time}: entry skipped; no qualifying call for {selected_expiry}."
            )
            return

        selected = sorted(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )[0]

        ticket = self.MarketOrder(selected.Symbol, 1)
        self._entry_order_id = ticket.OrderId
        self._held_option = selected.Symbol
        self._held_expiry = selected.Expiry.date()
        self._entry_price = None

        self.Debug(
            f"{self.Time}: entry submitted: {selected.Symbol}, "
            f"expiry {selected.Expiry.date()}, strike {selected.Strike}."
        )

    def _check_profit_target(self, data: Slice):
        if self._held_option is None or not self.Portfolio[self._held_option].Invested:
            return

        if self._entry_price is None or self._entry_price <= 0:
            return

        if self._order_is_open(self._exit_order_id):
            return

        if self._option_symbol not in data.OptionChains:
            return

        held_contract = None
        for contract in data.OptionChains[self._option_symbol]:
            if contract.Symbol == self._held_option:
                held_contract = contract
                break

        if held_contract is None:
            return

        bid = held_contract.BidPrice
        ask = held_contract.AskPrice
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self._entry_price * 1.50:
            self._submit_exit("profit target")

    def _time_stop(self):
        if self._held_option is None or not self.Portfolio[self._held_option].Invested:
            return

        if self._held_expiry is None:
            return

        previous_trading_day = self._previous_trading_day(self._held_expiry)
        if self.Time.date() == previous_trading_day:
            self._submit_exit("15:45 pre-expiration time stop")

    def _expiration_safety_check(self):
        if self._held_option is None or not self.Portfolio[self._held_option].Invested:
            return

        if self._held_expiry is not None and self.Time.date() >= self._held_expiry:
            self._no_entry_date = self.Time.date()
            self._submit_exit("expiration safety liquidation")

    def _previous_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self._spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _submit_exit(self, reason):
        if self._held_option is None:
            return

        if self._order_is_open(self._exit_order_id):
            return

        quantity = self.Portfolio[self._held_option].Quantity
        if quantity == 0:
            return

        # Cancel any previously open exit order before sending the one required
        # market liquidation order.
        for order in self.Transactions.GetOpenOrders(self._held_option):
            if order.Id != self._entry_order_id:
                self.Transactions.CancelOrder(order.Id)

        ticket = self.MarketOrder(self._held_option, -quantity)
        self._exit_order_id = ticket.OrderId
        self.Debug(f"{self.Time}: exit submitted ({reason}): {self._held_option}.")

    def _handle_unexpected_spy_position(self):
        if not self.Portfolio[self._spy].Invested:
            return

        if self._order_is_open(self._spy_liquidation_order_id):
            return

        quantity = self.Portfolio[self._spy].Quantity
        if quantity != 0:
            ticket = self.MarketOrder(self._spy, -quantity)
            self._spy_liquidation_order_id = ticket.OrderId
            self.Debug(
                f"{self.Time}: unexpected SPY exercise/assignment position; "
                f"liquidation submitted."
            )

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.OrderId == self._entry_order_id:
            if order_event.Status == OrderStatus.Filled and order_event.FillQuantity > 0:
                self._entry_price = order_event.FillPrice
                self.Debug(
                    f"{self.Time}: entry filled: {self._held_option} "
                    f"at {self._entry_price:.2f}."
                )

            if order_event.Status in (
                OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid
            ):
                if order_event.Status != OrderStatus.Filled:
                    self.Debug(f"{self.Time}: entry did not fill; selection cleared.")
                    self._held_option = None
                    self._held_expiry = None
                    self._entry_price = None
                self._entry_order_id = None

        if order_event.OrderId == self._exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"{self.Time}: option exit filled.")
                self._held_option = None
                self._held_expiry = None
                self._entry_price = None

            if order_event.Status in (
                OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid
            ):
                self._exit_order_id = None

        if order_event.OrderId == self._spy_liquidation_order_id:
            if order_event.Status in (
                OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid
            ):
                self._spy_liquidation_order_id = None

        # Assignment/exercise can be reflected before the next Slice.
        self._handle_unexpected_spy_position()

    def _order_is_open(self, order_id):
        if order_id is None:
            return False

        ticket = self.Transactions.GetOrderTicket(order_id)
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )
